  Lemma sw_pw : forall M M' (su : Z) bufp bufsz LB cr VM g,
    sw_post M su 0xc7a38 bufp bufsz M' -> (bv_unsigned sp0 - 8388608 + 112 <= su)%Z -> (su <= bv_unsigned sp0)%Z ->
